"""Report the isolated input-change experiments; never promote clipped waves."""
from pathlib import Path
import json
import numpy as np,pandas as pd
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import broad_study as b
from test_input_sensitivity48 import OUT,CASES,BASE,NODES,WIDTHS,KERNEL
rows=[json.loads(p.read_text()) for p in sorted(OUT.glob('*/result.json'))];assert len(rows)==22,len(rows);assert all(x['finite_and_no_clipping'] for x in rows if x['length']==100)
assert all(x['audit']['clipping_volume_m3']>1e-6 for x in rows if x['length']==50)
b.save(OUT/'all_results.json',rows)
lookup={(x['case'],x['length'],x['cfl']):x for x in rows};labels={'baseline':'Baseline','width36':'Width 36','slope36_half':'Half slope 36','outlet_raw':'Raw outlet','width36_slope36_half':'Width + half slope','width36_outlet_raw':'Width + outlet','slope36_half_outlet_raw':'Half slope + outlet','all_half':'All (half slope)','heads36_raw':'Raw heads 36','all_raw':'All (raw heads)'}
fig=make_subplots(rows=2,cols=2,subplot_titles=['100 m: input changes with fixed roughness','50 m: invalid hydrographs — clipping persists','50 m: artificial water added by depth clipping','Steady state: local improvements versus unchanged reaches'],vertical_spacing=.18,horizontal_spacing=.1)
force=b.forcing('48');start=force.loc[force.phase.eq('input_event'),'time_utc'].min()-pd.Timedelta(hours=4);end=force.loc[force.phase.eq('input_event'),'time_utc'].max()+pd.Timedelta(hours=12)
selected=[('baseline','#111111'),('width36','#0072B2'),('outlet_raw','#009E73'),('all_half','#D55E00'),('all_raw','#CC79A7')]
def add(w,label,color,row,col,dash='solid',show=True):
 w=w[(w.time_utc>=start)&(w.time_utc<=end)];q=w.q_outlet_cms.to_numpy();ii={0,len(w)-1}
 for i in range(0,len(w),5):ii.update([i+int(np.argmin(q[i:i+5])),i+int(np.argmax(q[i:i+5]))])
 z=w.iloc[sorted(ii)];fig.add_trace(go.Scatter(x=z.time_utc,y=z.q_outlet_cms,name=label,legendgroup=label,showlegend=show,line=dict(color=color,dash=dash)),row=row,col=col)
mc=pd.read_parquet(b.OUT/'investigation/current_mc/states/48/S000_base/outlet.parquet')
for col,length in [(1,100),(2,50)]:
 add(mc,'Current MC','#777777',1,col,'dash',col==1)
 for case,color in selected:add(pd.read_parquet(Path(lookup[(case,length,.35)]['folder'])/'wave.parquet'),labels[case],color,1,col,show=col==1)
 fig.update_xaxes(title_text='UTC',row=1,col=col);fig.update_yaxes(title_text='Outlet discharge (m³/s)',row=1,col=col)
fig.add_trace(go.Bar(x=[labels[c] for c in CASES],y=[lookup[(c,50,.35)]['audit']['clipping_volume_m3']/1e6 for c in CASES],name='50 m clipping volume',marker_color='#D55E00'),row=2,col=1);fig.update_yaxes(title_text='Artificial water (million m³)',row=2,col=1);fig.update_xaxes(tickangle=-25,row=2,col=1)
for case,color in [('baseline','#777777'),('all_half','#D55E00')]:
 hydro={x['reach']:x for x in lookup[(case,50,.35)]['initial_hydraulics']};ids=[36,65,161,188];fig.add_trace(go.Bar(x=[str(x) for x in ids],y=[hydro[x]['max_outgoing_face_Fr'] for x in ids],name=labels[case]+' — starting Fr',marker_color=color),row=2,col=2)
fig.update_xaxes(title_text='Physical reach',type='category',row=2,col=2);fig.update_yaxes(title_text='Maximum outgoing-face Froude number',row=2,col=2)
fig.update_layout(template='plotly_white',height=1100,width=1500,title='Example 48: reach-36 and outlet input changes do not resolve the refined-grid failure',barmode='group',legend=dict(orientation='h',y=-.28),margin=dict(b=240),hovermode='x unified');fig.write_html(OUT/'input_sensitivity_plotly.html',include_plotlyjs=True);b.save(OUT/'plot_expected.json',dict(traces=len(fig.data),subplots=4))
lines=['Example 48: reach 36 and outlet input sensitivity','', 'SCOPE','Input-only diagnostic. Original supplied-type local-inertial kernel with critical-flow cap retained; no positivity limiter, no q-centred smoothing. Fixed n=.020799605931143154, forcing, topology and reach lengths. Each variant re-equilibrated under its own geometry, then run through the same event. Original data and production settings were not edited.','', 'CHANGES TESTED','W: restore reach 36 wet measured width, 21.319629 -> 158.592645 m. This tests removing the flagged correction; it does not assert the measurement is hydraulically correct.','R: halve reach 36 head drop while preserving its midpoint elevation. Node 24 falls by .11646 m and node 25 rises by .11646 m; slope 3.813649 -> 1.906824 m/km. Both node values are shared by every incident reach, so slopes of reaches 33,35,36,37,38 change consistently. This is an explicitly artificial sensitivity, not an observation correction.','O: raise outlet node 126 from 1733.961265 to raw matched WSE 1737.680160 m. Keep upstream node 125 fixed. Terminal reach-188 slope becomes 1.996035 instead of 2.352452 m/km. The normal-flow outlet closure remains in place and uses the updated terminal slope. This tests the geometry AND its consistent normal-flow rating, not a different boundary-condition type.','All eight W/R/O combinations were tested at 100 and 50 m. Two additional cases use raw WSE at nodes 24/25: 1916.758400 and 1915.692170 m; reach-36 slope then becomes 8.728621 m/km (steeper, not flatter). Raw36 alone and W+raw36+O were run at both grids. W+O and W+R+O were also repeated at 50 m, CFL .175. Total 22 completed event simulations, each with steady-state preparation.','', 'CHECKS','All variant widths/slopes remain positive; connected reaches retain identical node heads. Actual solver inputs are saved as event_input.npz; copied physical_parameters.parquet includes historical MC metadata that is not used by the dynamic solver. Manning n in the solver and result metadata is authoritative. Every steady state met max cell flow imbalance / inlet flow <1e-8. Spinup clipping is recorded separately and is not silently treated as validation.','', 'RESULTS','Case | max cell length m | CFL | clipping million m3 | maximum depth m | outlet feature height m3/s | first clipping sample hour']
for length in [100,50]:
 for case in CASES:
  x=lookup[(case,length,.35)];a=x['audit'];t='none' if x['first_clipping_sample_hours'] is None else f"{x['first_clipping_sample_hours']:.3f}";lines.append(f"{labels[case]} | {length} | .35 | {a['clipping_volume_m3']/1e6:.5f} | {a['maximum_depth_m']:.4f} | {x['feature_height_cms']:.3f} | {t}")
for case in ['width36_outlet_raw','all_half']:
 x=lookup[(case,50,.175)];a=x['audit'];lines.append(f"{labels[case]} | 50 | .175 | {a['clipping_volume_m3']/1e6:.5f} | {a['maximum_depth_m']:.4f} | {x['feature_height_cms']:.3f} | {x['first_clipping_sample_hours']}")
lines+=['', 'INTERPRETATION','Every 100 m event remains free of negative-depth clipping. Every tested 50 m event still clips negative depths, including combined changes and smaller-CFL controls. These 50 m hydrographs are invalid predictions: clipping creates water. Differences in spike size or clipping volume are not treated as a ranking of input plausibility; the unstable trajectories can depend on very small initial-state differences.','', 'LOCAL RESPONSE (50 m steady state; maximum outgoing-face Fr includes reach-end faces)']
for case in ['baseline','width36','outlet_raw','all_half']:
 x=lookup[(case,50,.35)];lines.append(labels[case])
 for z in x['initial_hydraulics']:
  if z['reach'] in [36,65,161,188]:lines.append(f"  Reach {z['reach']}: mean depth {z['mean_depth_m']:.5f} m; maximum outgoing-face Fr {z['max_outgoing_face_Fr']:.5f}; terminal reach flow {z['outflow_cms']:.4f} m3/s.")
lines+=['', 'The restored width improves local conditions at reach 36; the adjusted outlet reduces the terminal slope and changes depth there. These local improvements do not eliminate the broader unstable regime. This supports the prior straight-channel benchmark evidence that the problem is not solely a bottleneck at reach 36 or this particular outlet elevation adjustment.','It does NOT establish that the original width correction or outlet match is correct, or that no conceivable geometry/boundary alternative could help. No independent remapping or elevation survey was performed. The raw WSE alternative is not a verified bed elevation.','', 'DECISION','None of these input variants is promoted into the production setup. Review the flagged width and outlet match on their own observational merits; do not tune them to suppress instability. The tested corrections are insufficient to make the current local-inertial formulation reliable at 50 m under the fixed roughness and forcing. A 25 m follow-up was not warranted because no 50 m variant passed the basic no-clipping requirement.']
(OUT/'findings.txt').write_text('\n'.join(lines)+'\n');b.save(OUT/'source_manifest.json',{str(p):b.sha(p) for p in [BASE,NODES,WIDTHS,KERNEL,Path(__file__),Path(__file__).with_name('test_input_sensitivity48.py')]});print(OUT/'input_sensitivity_plotly.html');print('runs',len(rows),'traces',len(fig.data))
